// Package service registers `cloudedits serve` with the operating system's
// per-user service manager so the library keeps running after the setup
// wizard closes, after logout/login and after a reboot:
//
//   - macOS: a launchd LaunchAgent in ~/Library/LaunchAgents.
//   - Linux: a systemd --user unit in ~/.config/systemd/user.
//   - Windows: a Task Scheduler task with a logon trigger for the current user.
//
// All three are per-user and need no administrator rights. Install, Uninstall
// and Status are idempotent. The unit files are generated by pure functions
// (LaunchdPlist, SystemdUnit, TaskXML) so every platform's output is tested on
// every platform.
package service

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"slices"
	"strings"
)

// Default names. The launchd label matches the macOS app bundle identifier.
const (
	DefaultLabel       = "toys.hdr.cloudedits"
	DefaultSystemdName = "cloudedits"
	DefaultTaskName    = "cloudedits"
)

// Spec describes the process the service manager keeps running.
type Spec struct {
	// Name is the launchd label, systemd unit name (without .service) or
	// Task Scheduler task name.
	Name string
	// Executable is the absolute path of the cloudedits binary.
	Executable string
	// Args are the arguments after the executable, e.g. serve --data-dir D.
	Args []string
	// LogPath receives stdout and stderr where the manager supports it.
	LogPath string
	// WorkingDir is the process working directory.
	WorkingDir string
	// User is the Windows account (DOMAIN\user) the logon trigger fires for.
	User string
}

// Status is what the service manager reports for a Spec.
type Status struct {
	Manager   string `json:"manager"` // "launchd" | "systemd" | "schtasks"
	Name      string `json:"name"`
	UnitPath  string `json:"unitPath,omitempty"`
	Installed bool   `json:"installed"`
	// Loaded is true when the manager has the unit active (launchd loaded,
	// systemd enabled, task registered and enabled).
	Loaded bool   `json:"loaded"`
	Detail string `json:"detail,omitempty"`
}

// Manager installs and removes the per-user service.
type Manager interface {
	Install(ctx context.Context, spec Spec) (Status, error)
	Uninstall(ctx context.Context, name string) (Status, error)
	Status(ctx context.Context, name string) (Status, error)
	// DefaultName is the unit name this platform uses when none is given.
	DefaultName() string
}

// Runner executes a service-manager command and returns its combined output.
type Runner func(ctx context.Context, name string, args ...string) (string, int, error)

// ErrUnsupported is returned on platforms without a supported service manager.
var ErrUnsupported = errors.New("no supported per-user service manager on this platform")

// New returns the Manager for the running platform.
func New() (Manager, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return nil, fmt.Errorf("home directory: %w", err)
	}
	return newFor(runtime.GOOS, home, os.Getenv("XDG_CONFIG_HOME"), os.Getuid(), execRunner)
}

func newFor(goos, home, xdgConfig string, uid int, run Runner) (Manager, error) {
	switch goos {
	case "darwin":
		return &launchd{dir: filepath.Join(home, "Library", "LaunchAgents"), uid: uid, run: run}, nil
	case "linux":
		if xdgConfig == "" {
			xdgConfig = filepath.Join(home, ".config")
		}
		return &systemd{dir: filepath.Join(xdgConfig, "systemd", "user"), run: run}, nil
	case "windows":
		return &schtasks{run: run, tmpDir: os.TempDir()}, nil
	default:
		return nil, ErrUnsupported
	}
}

// secretEnvVars are never passed to service-manager commands, so a
// credential in the caller's environment cannot leak into a unit or task.
var secretEnvVars = []string{"TS_AUTHKEY", "TS_AUTH_KEY", "CLOUDEDITS_TOKEN"}

// WithoutSecrets returns environ without cloudedits credentials.
func WithoutSecrets(environ []string) []string {
	out := make([]string, 0, len(environ))
	for _, kv := range environ {
		name, _, _ := strings.Cut(kv, "=")
		if slices.ContainsFunc(secretEnvVars, func(s string) bool { return strings.EqualFold(s, name) }) {
			continue
		}
		out = append(out, kv)
	}
	return out
}

func execRunner(ctx context.Context, name string, args ...string) (string, int, error) {
	cmd := exec.CommandContext(ctx, name, args...)
	cmd.Env = WithoutSecrets(os.Environ())
	out, err := cmd.CombinedOutput()
	code := 0
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		code = exitErr.ExitCode()
		err = nil
	}
	return string(out), code, err
}

// ResolveExecutable returns the path a service should start. exe is the
// running binary (os.Executable). Inside an AppImage the binary lives in a
// temporary mount, so the AppImage file itself is used. A binary built by
// `go run` or `go test` lives in a temporary build directory that is deleted
// when the command exits; installing a service pointing at it would leave a
// service that can never start.
func ResolveExecutable(exe string, getenv func(string) string) (string, error) {
	if appImage := strings.TrimSpace(getenv("APPIMAGE")); appImage != "" && strings.HasPrefix(exe, strings.TrimSpace(getenv("APPDIR"))) {
		exe = appImage
	}
	abs, err := filepath.Abs(exe)
	if err != nil {
		return "", err
	}
	for _, part := range strings.Split(filepath.ToSlash(abs), "/") {
		if strings.HasPrefix(part, "go-build") {
			return "", fmt.Errorf("%s is a temporary build; install the service from an installed cloudedits binary", abs)
		}
	}
	return abs, nil
}

func ensureSpec(spec Spec) error {
	if strings.TrimSpace(spec.Name) == "" {
		return errors.New("service name is empty")
	}
	if !filepath.IsAbs(spec.Executable) {
		return fmt.Errorf("executable %q is not an absolute path", spec.Executable)
	}
	return nil
}

func writeFileAtomic(path string, data []byte, perm os.FileMode) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, perm); err != nil {
		return err
	}
	if err := os.Rename(tmp, path); err != nil {
		_ = os.Remove(tmp)
		return err
	}
	return nil
}

func commandError(what string, out string, code int, err error) error {
	if err != nil {
		return fmt.Errorf("%s: %w", what, err)
	}
	return fmt.Errorf("%s exited %d: %s", what, code, strings.TrimSpace(out))
}
